///
/// Accepts the wildcard and a comma-separated list of strong ETags, comparing
/// each against the current tag.
fn etag_matches(if_match: &str, current_etag: &str) -> bool {
    let if_match = if_match.trim();
    if if_match == "*" {
        return true;

